// calendar-adapter (live): section 13 contract over the Google Calendar API v3.
const i = $input.first().json;
const cal = encodeURIComponent($env.GOOGLE_CALENDAR_ID);
const base = 'https://www.googleapis.com/calendar/v3';
const tz = $env.BUSINESS_TZ || 'America/New_York';
switch (i.op) {
  case 'busy':
    return [{ json: { op: i.op, method: 'POST', url: base + '/freeBusy',
      body: { timeMin: i.from, timeMax: i.to, items: [{ id: $env.GOOGLE_CALENDAR_ID }] } } }];
  case 'get_event':
    return [{ json: { op: i.op, method: 'GET', url: base + '/calendars/' + cal + '/events/' + encodeURIComponent(i.event_id || '') } }];
  case 'create_event':
    return [{ json: { op: i.op, method: 'POST', url: base + '/calendars/' + cal + '/events',
      body: { id: i.event_id, summary: i.summary || '', description: i.description || '', location: i.location || '',
        start: { dateTime: i.start, timeZone: tz }, end: { dateTime: i.end, timeZone: tz } } } }];
  default:
    return [{ json: { op: i.op, invalid: true } }];
}

// Maps an HTTP status (or a network failure) to the section 13 error kinds.
function fail(kind, message) { return [{ json: { ok: false, error: { kind, message: String(message).slice(0, 300) } } }]; }
function httpFail(res, what) {
  if (!res || res.statusCode === undefined) return fail('unavailable', what + ': ' + JSON.stringify((res && res.error) || res).slice(0, 200));
  const s = res.statusCode;
  const msg = what + ' ' + s + ': ' + JSON.stringify(res.body).slice(0, 200);
  if (s === 429 || s >= 500) return fail('unavailable', msg);
  if (s === 404 || s === 410) return fail('not_found', msg);
  if (s === 409) return fail('conflict', msg);
  if (s === 401 || s === 403) return fail('unavailable', msg);
  return fail('invalid', msg);
}
const ok2xx = (res) => res && res.statusCode >= 200 && res.statusCode < 300;


const req = $('calendar:request').first().json;
if (req.invalid) return fail('invalid', 'unknown op ' + JSON.stringify(req.op) + ' for calendar');
const res = $input.first().json;
const body = (res && res.body) || {};
const iso = (t) => (t && (t.dateTime || t.date)) || null;
if (req.op === 'get_event') {
  if (res && (res.statusCode === 404 || res.statusCode === 410)) return [{ json: { ok: true, found: false, status: null, start: null, end: null } }];
  if (!ok2xx(res)) return httpFail(res, 'get_event');
  return [{ json: { ok: true, found: true, status: body.status || 'confirmed', start: iso(body.start), end: iso(body.end) } }];
}
if (!ok2xx(res)) return httpFail(res, req.op);
if (req.op === 'busy') {
  const c = (body.calendars || {})[$env.GOOGLE_CALENDAR_ID] || Object.values(body.calendars || {})[0] || {};
  if (c.errors && c.errors.length) return fail(c.errors[0].reason === 'notFound' ? 'not_found' : 'unavailable', 'freeBusy: ' + JSON.stringify(c.errors));
  return [{ json: { ok: true, busy: (c.busy || []).map((b) => ({ start: b.start, end: b.end })) } }];
}
return [{ json: { ok: true, event_id: body.id } }];
